, "id": "3e903609-f6b7-593b-83b3-8278abaedb5d", "subject_id": "8f6d8d06-518a-51e1-bae4-c126a7744c58", "source_id": "0971c8d1-d61a-5ada-9923-ad849637ab04"}, {"subject_table": "event", "field_path": "description", "claim_text": "庄宗死后近侍散去，善友收乐器覆盖尸体焚烧。", "citation": "卷275·同光四年（926）·zztj-v275-y0926-p001·原文件第6行", "note": "原文：李彦卿等恸哭而去，左右皆散，善友敛庑下乐器覆帝尸而焚之。；核对说明：焚尸与庄宗中矢死分动作；不推善友是杀帝者或宗教火葬礼主持。", "status": "draft", "id": "06a9c6e2-9309-5dcf-87c3-da53afdd46dc", "subject_id": "ca9b22a3-2661-5c17-b3f5-b0a2d9a87f0c", "source_id": "dd5f7882-cc91-5cd1-a3d3-55ffc0f58173"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "926年四月丁亥朔庄宗死后", "citation": "卷275·同光四年（926）·zztj-v275-y0926-p001·原文件第6行", "note": "原文：李彦卿等恸哭而去，左右皆散，善友敛庑下乐器覆帝尸而焚之。；核对说明：按主书及对应补证纪时；追叙或他书记载另作说明，不自行换算公历日期。", "status": "draft", "id": "dba4a105-2998-5cc1-a7c1-f0245f788e0b", "subject_id": "ca9b22a3-2661-5c17-b3f5-b0a2d9a87f0c", "source_id": "dd5f7882-cc91-5cd1-a3d3-55ffc0f58173"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "符彦卿：恸哭离去者。", "citation": "卷275·同光四年（926）·zztj-v275-y0926-p001·原文件第6行", "note": "原文：李彦卿等恸哭而去，左右皆散，善友敛庑下乐器覆帝尸而焚之。；核对说明：参与身份依据本句；人名沿用已有主体，原文不改字。", "status": "draft", "id": "8daf91f0-53a5-5ea5-a8b1-ae68257ad012", "subject_id": "46963b74-7653-5062-8eb1-331b63fa17da", "source_id": "dd5f7882-cc91-5cd1-a3d3-55ffc0f58173"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "善友（庄宗鹰坊人）：收乐器焚尸者。", "citation": "卷275·同光四年（926）·zztj-v275-y0926-p001·原文件第6行", "note": "原文：李彦卿等恸哭而去，左右皆散，善友敛庑下乐器覆帝尸而焚之。；核对说明：参与身份依据本句；人名沿用已有主体，原文不改字。", "status": "draft", "id": "18f8412d-4575-5a68-a1ba-c7bc637ad382", "subject_id": "d2d9d907-7a21-5781-9940-2fb890b1154d", "source_id": "dd5f7882-cc91-5cd1-a3d3-55ffc0f58173"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "李存勖：被焚遗体之人。", "citation": "卷275·同光四年（926）·zztj-v275-y0926-p001·原文件第6行", "note": "原文：李彦卿等恸哭而去，左右皆散，善友敛庑下乐器覆帝尸而焚之。；核对说明：参与身份依据本句；人名沿用已有主体，原文不改字。", "status": "draft", "id": "a73d3325-b485-57fe-ac5b-e423a34b4d09", "subject_id": "ed13aafe-2fe6-541e-b6e2-69ec8d8f7211", "source_id": "dd5f7882-cc91-5cd1-a3d3-55ffc0f58173"}, {"subject_table": "event", "field_path": "description", "claim_text": "旧庄宗纪也记五坊人善友以乐器簇尸焚之，明宗入洛仅得燼骨。", "citation": "《旧五代史》卷三十四，段落 jiu-wudaishi-205deb4a7860-p001069；EPUB电子本，纸本及异文待核", "note": "原文：是時，帝之左右例皆奔散，唯五坊人善友斂廓下樂器簇於帝屍之上，發火焚之。及明宗入洛，止得其燼骨而已。；核对说明：五坊与鹰坊为各书职称，不为此补姓；后得骨用于同事件补证。", "status": "draft", "id": "33a90404-fb3d-5ed6-b88b-afa40f74a8ba", "subject_id": "ca9b22a3-2661-5c17-b3f5-b0a2d9a87f0c", "source_id": "ae5ea026-a2b7-59b3-a904-a73ff3eb2457"}, {"subject_table": "event", "field_path": "description", "claim_text": "刘后携金宝与李存渥、元行钦率七百骑焚喜庆殿，经师子门出逃。", "citation": "卷275·同光四年（926）·zztj-v275-y0926-p001·原文件第6行", "note": "原文：刘后囊金宝系马鞍，与申王存屋及李绍荣引七百骑，焚喜庆殿，自师子门出走。；核对说明：主存屋据同申王与旧宗室传同刘后奔太原校李存渥，原屋保留；七百为书载同逃骑兵，不造个人财额。", "status": "draft", "id": "658d04e2-a9aa-504c-8b8b-914934568fed", "subject_id": "b98b1c5a-07b6-5b04-b2a9-15d1100441c0", "source_id": "dd5f7882-cc91-5cd1-a3d3-55ffc0f58173"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "926年四月丁亥朔宫乱后", "citation": "卷275·同光四年（926）·zztj-v275-y0926-p001·原文件第6行", "note": "原文：刘后囊金宝系马鞍，与申王存屋及李绍荣引七百骑，焚喜庆殿，自师子门出走。；核对说明：按主书及对应补证纪时；追叙或他书记载另作说明，不自行换算公历日期。", "status": "draft", "id": "d557806f-cbf5-5d53-ad73-3c62a292b984", "subject_id": "b98b1c5a-07b6-5b04-b2a9-15d1100441c0", "source_id": "dd5f7882-cc91-5cd1-a3d3-55ffc0f58173"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "刘夫人（李存勖妻）：携财出逃者。", "citation": "卷275·同光四年（926）·zztj-v275-y0926-p001·原文件第6行", "note": "原文：刘后囊金宝系马鞍，与申王存屋及李绍荣引七百骑，焚喜庆殿，自师子门出走。；核对说明：参与身份依据本句；人名沿用已有主体，原文不改字。", "status": "draft", "id": "b1c8e36a-ce3e-5559-b5ec-771d18f8c851", "subject_id": "679b875b-3f4c-5037-9e22-6a60e9c161e3", "source_id": "dd5f7882-cc91-5cd1-a3d3-55ffc0f58173"}, {"subject_table": "person", "field_path": "description", "claim_text": "本段记李存渥：申王、同逃者。", "citation": "卷275·同光四年（926）·zztj-v275-y0926-p001·原文件第6行", "note": "原文：刘后囊金宝系马鞍，与申